def fact(n):
    if n <= 1:
        return 1
    return n * fact(n - 1)
print(fact(4))

def total(n):
    if n == 0:
        return 0
    return n + total(n - 1)
print(total(3))

def down(n):
    if n == 0:
        return
    print(n)
    down(n - 1)
down(3)

def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)
print(fib(5))

calls = 0
def fib(n):
    global calls
    calls += 1
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)
fib(4)
print(calls)

def walk(path, n):
    if len(path) == n:
        print(''.join(path))
        return
    for ch in ['a', 'b']:
        path.append(ch)
        walk(path, n)
        path.pop()
walk([], 2)

def g(n):
    if n == 0:
        return 1
    return g(n - 1) + g(n - 1) + g(n - 1)
print(g(3))
